99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
102	        HttpHeaders headers = new HttpHeaders();
103	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
104	        if (this.clinicService.isTelephoneInUse(owner.getTelephone())) {
105	            return new ResponseEntity<>(HttpStatus.CONFLICT);
106	        }
107	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
108	        boolean householdInUse = this.clinicService.isHouseholdInUse(owner.getLastName(), owner.getAddress());
109	        if (householdInUse) {
110	            if (!sharesHousehold) {
111	                return new ResponseEntity<>(HttpStatus.CONFLICT);
112	            }
113	            // Joining an existing household: assign the shared, stable household identifier to
114	            // the new owner (and back-fill the existing member(s)).
115	            this.clinicService.assignHousehold(owner);
116	        }
117	        owner.setNamesakeCount(
118	            this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
119	        this.clinicService.saveOwner(owner);
120	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
121	        headers.setLocation(UriComponentsBuilder.newInstance()
122	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
123	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
124	    }
