279	    @Override
280	    @Transactional(readOnly = true)
281	    public boolean isTelephoneInUse(String telephone) throws DataAccessException {
282	        String normalized = ownerMapper.normalizeTelephone(telephone);
283	        if (normalized == null) {
284	            return false;
285	        }
286	        return ownerRepository.findAll().stream()
287	            .map(existing -> ownerMapper.normalizeTelephone(existing.getTelephone()))
288	            .anyMatch(normalized::equals);
289	    }
290	
291	    @Override
292	    @Transactional(readOnly = true)
293	    public boolean isHouseholdInUse(String lastName, String address) throws DataAccessException {
294	        String normalizedLastName = normalizeHouseholdValue(lastName);
295	        String normalizedAddress = normalizeHouseholdValue(address);
296	        if (normalizedLastName == null || normalizedAddress == null) {
297	            return false;
298	        }
299	        return ownerRepository.findAll().stream()
300	            .anyMatch(existing -> inHousehold(existing, normalizedLastName, normalizedAddress));
301	    }
302	
303	    /**
304	     * Canonicalize a last name or address for household comparison: trim, collapse every run of
305	     * whitespace to a single space and lower-case the result, so values that differ only in
306	     * letter case or incidental whitespace are treated as equal.
307	     */
308	    private String normalizeHouseholdValue(String value) {
309	        if (value == null) {
310	            return null;
311	        }
312	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
313	    }
314	
315	    /**
316	     * Single definition of household membership: an owner belongs to the household identified by
317	     * the given already-normalized last name and address when its own normalized last name and
318	     * address match. Keeping this in one place means the household-equality rule is changed once.
319	     */
320	    private boolean inHousehold(Owner existing, String normalizedLastName, String normalizedAddress) {
321	        return normalizedLastName.equals(normalizeHouseholdValue(existing.getLastName()))
322	            && normalizedAddress.equals(normalizeHouseholdValue(existing.getAddress()));
323	    }
