325	    @Override
326	    @Transactional
327	    public String assignHousehold(Owner owner) throws DataAccessException {
328	        String householdId = generateHouseholdId(owner.getLastName(), owner.getAddress());
329	        owner.setHouseholdId(householdId);
330	        String normalizedLastName = normalizeHouseholdValue(owner.getLastName());
331	        String normalizedAddress = normalizeHouseholdValue(owner.getAddress());
332	        if (normalizedLastName != null && normalizedAddress != null) {
